package com.ethk3.novaonepro.strategyv2;
import java.io.*;import java.lang.reflect.*;import java.nio.*;import java.util.*;
public final class R26SymbolicDiagnosticsTest {
 static void check(boolean x,String why){if(!x)throw new AssertionError(why);}
 static Object get(SymbolicFamilyR26 m,String n)throws Exception{Field f=SymbolicFamilyR26.class.getDeclaredField(n);f.setAccessible(true);return f.get(m);}
 static double[][] features(SymbolicFamilyR26 m)throws Exception{Method f=SymbolicFamilyR26.class.getDeclaredMethod("featureTable");f.setAccessible(true);return (double[][])f.invoke(m);}
 static byte[] save(SymbolicFamilyR26 m)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
 static SymbolicFamilyR26 restore(String family,byte[] b)throws Exception{SymbolicFamilyR26 m=new SymbolicFamilyR26(family);m.read(new DataInputStream(new ByteArrayInputStream(b)));return m;}
 static byte[] old(byte[] b){byte[] r=Arrays.copyOf(b,b.length-9);ByteBuffer.wrap(r).putInt(0x26131401);return r;}
 static double loss(double[][] w,double[][] f,int[] d){double[][] s=new double[10][10];for(int p=0;p<10;p++)for(int n=0;n<10;n++)for(int j=0;j<5;j++)s[p][n]+=w[p*10+n][j]*f[p][j];int[] zero=d.clone();for(int i=0;i<10;i++)zero[i]--;return ExactPermutationR26.nll(s,zero,ExactPermutationR26.infer(s,null));}
 static int[] draw(Random r){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int j=r.nextInt(i+1),v=d[i];d[i]=d[j];d[j]=v;}return d;}
 public static void main(String[] args)throws Exception{
  double maxError=0;int coordinates=0;
  for(String family:new String[]{"F13","F14"}){SymbolicFamilyR26 m=new SymbolicFamilyR26(family);Random random=new Random(261314);for(int i=0;i<30;i++)m.update(draw(random));byte[] start=save(m);double[][] f=features(m),w=(double[][])get(m,"weight"),v=(double[][])get(m,"momentum");int[] target=draw(random);double[][] numeric=new double[100][5];for(int k=0;k<50;k++){int row=(k*17)%100,j=k%5;double original=w[row][j],eps=1e-5;w[row][j]=original+eps;double plus=loss(w,f,target);w[row][j]=original-eps;double minus=loss(w,f,target);w[row][j]=original;numeric[row][j]=(plus-minus)/(2*eps);coordinates++;}
   double before=loss(w,f,target);m.update(target);TrainingDiagnosticsR26.Step step=m.lastTrainingStep();double[][] actual=(double[][])get(m,"weight"),velocity=(double[][])get(m,"momentum");check(Math.abs(before-step.lossBefore)<1e-12&&Math.abs(loss(actual,f,target)-step.lossAfter)<1e-12,"loss changed pre-label features");double delta2=0,gradient2=0;for(int row=0;row<100;row++)for(int j=0;j<5;j++){double g=(velocity[row][j]-.9*v[row][j])/.1;gradient2+=g*g;double d=actual[row][j]-w[row][j];delta2+=d*d;}check(Math.abs(Math.sqrt(gradient2)-step.gradientNorm)<1e-12&&Math.sqrt(delta2)==step.parameterDeltaNorm,"gradient/delta norms include wrong state");
   for(int k=0;k<50;k++){int row=(k*17)%100,j=k%5;double g=(velocity[row][j]-.9*v[row][j])/.1;maxError=Math.max(maxError,Math.abs(g-numeric[row][j]));check(Math.abs(g-numeric[row][j])<1e-8,"joint NLL derivative differs");}
   SymbolicFamilyR26 alternative=restore(family,start);alternative.update(draw(random));check(step.inputHash.equals(alternative.lastTrainingStep().inputHash),"target in input hash");SymbolicFamilyR26 next=restore(family,save(m));target=draw(random);m.update(target);next.update(target);check(Arrays.equals(save(m),save(next)),"next update after restore differs");long updates=m.completedTrainingUpdates();m.resetTemporalContext();check(m.completedTrainingUpdates()==updates&&m.lastTrainingStep()==null,"gap erased lifetime");next=restore(family,save(m));target=draw(random);m.update(target);next.update(target);check(Arrays.equals(save(m),save(next)),"gap restore differs");
   byte[] good=save(m);SymbolicFamilyR26 legacy=restore(family,old(good));check(legacy.optimizerProtocol().endsWith("LEGACY_COUNTER_LOWER_BOUND")&&legacy.completedTrainingUpdates()==1,"legacy context clock claimed lifetime");check(Arrays.equals(old(good),old(save(legacy))),"legacy numbers changed");target=draw(random);m.update(target);legacy.update(target);check(Arrays.equals(old(save(m)),old(save(legacy))),"legacy next numerical update differs");
   m=restore(family,good);for(int kind=0;kind<3;kind++){byte[] bad=good.clone();if(kind==0)bad=Arrays.copyOf(bad,bad.length-2);if(kind==1)bad[bad.length-1]=2;if(kind==2)ByteBuffer.wrap(bad).putDouble(bad.length-17,Double.NaN);try{m.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("bad state accepted");}catch(IOException expected){}check(Arrays.equals(save(m),good),"failed restore changed retained state");}
   for(int budget:new int[]{1,20,150}){m=restore(family,good);ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,budget,()->false));boolean yielded=false;try{m.update(target);}catch(BudgetTokenSU1.Yield expected){yielded=true;}finally{ExecutionBudgetR26.leave();}check(yielded&&Arrays.equals(save(m),good)&&m.lastTrainingStep()==null,"interrupted exact inference changed parameters");}
   if(args.length>0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0],family+"-state.bin"),good);
  }
  System.out.println("R26_SYMBOLIC_DIAGNOSTICS_PASS|families=2|finiteDifferenceCoordinates="+coordinates+"|maximumGradientError="+maxError+"|exactJointNll=true|fixedPreLabelTypedFeatures=true|momentumRetained=true|legacyCounterLowerBound=true|restoreGapCancelAtomic=true|scope=SYNTHETIC_NOT_NATURAL_QUALITY");
 }
}
